{"content":[{"type":"text","text":".d-header {
    width: 100%;
    position: absolute;
    top: 0;
    z-index: 1001;
    background-color: $header_background;
    box-shadow: 0 2px 4px -1px rgba(0,0,0, .25);

    .docked & {
      position: fixed;
      backface-visibility: hidden;  /** do magic for scrolling performance **/
    }

    .contents {
      margin: 8px 0;

      @include flexbox();
      @include align-items(center);
    }

    .valign-helper {
      display: inline-block;
      height: 100%;
      vertical-align: middle;
    }

    #site-logo {
      max-height: 40px;
    }

    .fa-home {
      font-size: 1.643em;
    }

    .panel {
      position: relative;
      margin-left: auto;

      @include order(3);
    }

    .login-button, button.sign-up-button {
      float: left;
      margin-top: 7px;
      padding: 6px 10px;
      .fa { margin-right: 3px; }
    }

    button.login-button {
      margin-left: 7px;
    }

    .icons {
      float: left;
      text-align: center;
      margin: 0 0 0 5px;
      list-style: none;

      > li {
        float: left;
"}]}

{"content":[{"type":"text","text":"<div class='wrap'>
  <div class='contents clearfix'>

    {{home-logo minimized=showExtraInfo}}

    <div class='panel clearfix'>
      {{#unless currentUser}}
        {{#if showSignUpButton}}
          {{d-button action="showCreateAccount" class="btn-primary btn-small sign-up-button" label="sign_up"}}
        {{/if}}
        {{d-button action="showLogin" class="btn-primary btn-small login-button" icon="user" label="log_in"}}
      {{/unless}}
      <ul class='icons clearfix' role='navigation'>
        {{#if currentUser}}
          <li class='notifications'>
            <a class='icon' href {{action "showNotifications" target="view"}} data-notifications="notifications-dropdown" id='user-notifications' title='{{i18n 'notifications.title'}}'>
              {{fa-icon "comment" label="notifications.title"}}
            </a>
            {{#if currentUser.unread_notifications}}
              <a href class='badge-notification unread-notifications'>{{currentUser.unread_notifications}}</a>
            {{/if}}
            {{#if currentUser.unread_private_messages}}
              <a href class='badge-notification unread-private-messages'>{{currentUser.unread_private_messages}}</a>
            {{/if}}
          </li>
        {{/if}}
        <li>
          {{#if loginRequired}}
            <a id='search-button' class='icon expand' href='#' aria-hidden="true" {{action "showLogin"}}>
              {{fa-icon "search"}}
            </a>
          {{else}}
            <a id='search-button'
               class='icon expand'
               href='#'
               data-dropdown="search-dropdown"
               title='{{i18n 'search.title'}}'>
               {{fa-icon "search" label="search.title"}}
            </a>
          {{/if}}
        </li>
        <li class='categories dropdown'>
          {{#if loginRequired}}
            <a class='icon'
               href="#"
               aria-hidden="true"
               id="site-map"
               {{action "showLogin"}}>
               {{fa-icon "bars"}}
            </a>
          {{else}}
            <a class='icon'
               data-dropdown="site-map-dropdown"
               data-render="renderSiteMap"
               href
               title='{{i18n 'site_map'}}'
               aria-label='{{i18n 'site_map'}}'
               id="site-map">
               {{fa-icon "bars" label="site_map"}}
            </a>
          {{/if}}
          {{#if flaggedPostsCount}}
            <a href='/admin/flags/active' title='{{i18n 'notifications.total_flagged'}}' class='badge-notification flagged-posts'>{{flaggedPostsCount}}</a>
          {{/if}}
        </li>
        {{#if currentUser}}
          <li class='current-user dropdown'>
            <a class='icon'
               data-dropdown="user-dropdown"
               data-render="renderUserDropdown"
               href="#"
               title='{{i18n 'user.avatar.header_title'}}'
               aria-label='{{i18n 'user.avatar.header_title'}}'
               id="current-user">
                 {{bound-avatar currentUser "medium"}}
            </a>
          </li>
        {{/if}}
      </ul>

      {{#if view.renderDropdowns}}
        {{render "search"}}
        {{render "notifications" notifications}}

        {{#if view.renderSiteMap}}
          {{render "site-map"}}
        {{/if}}

        {{render "user-dropdown"}}
      {{/if}}
    </div>

    {{#if showExtraInfo}}
      {{header-extra-info topic=topic}}
    {{/if}}
  </div>
</div>
"}]}

{"content":[{"type":"text","text":"#topic-title {

  .title-wrapper {
    float: left;
    width: 90%;
    .btn-small {
      margin: 0 6px 0 0;
    }

    .badge-wrapper {
      float: left;
      &.bullet {
        margin-top: 5px;
      }
    }
  }

  a.badge-category {
    margin-top: 5px;
  }

  a.edit-topic i { font-size: 0.8em; }
}

.topic-title-outlet {
  clear: both;
}

.extra-info-wrapper {
  @include order(2);

  line-height: 1.5;
  .badge-wrapper {
    float: left;
  }

}

.has-pending-posts {
  padding: 0.5em;
  background-color: dark-light-diff($highlight, $secondary, 50%, -70%);
  a[href] {
    float: right;
  }
}
"}]}

{"content":[{"type":"text","text":"<div class="extra-info-wrapper">
  <div {{bind-attr class=":extra-info needsSecondRow:two-rows"}}>
    <div class="title-wrapper">
      <h1>
        {{#if showPrivateMessageGlyph}}
          <span class="private-message-glyph">{{fa-icon "envelope"}}</span>
        {{/if}}

        {{#if topic.details.loaded}}
          {{topic-status topic=topic}}
          <a class='topic-link' href='{{unbound topic.url}}' {{action "jumpToTopPost"}}>{{{topic.fancyTitle}}}</a>
        {{/if}}
      </h1>
      {{#if topic.details.loaded}}
        {{topic-category topic=topic}}
      {{/if}}
    </div>
  </div>
</div>
"}]}

{"content":[{"type":"text","text":"  td,th {
    padding: 3px 3px 3px 10px;
  }
  tr {
    border-bottom: 1px solid lighten($primary, 80%);
  }
}

.small-action {
  @include flexbox();
  @include align-items(center);

  .topic-avatar {
    padding: 5px 0;
    border-top: none;
    float: left;
    i {
      font-size: 35px;
      width: 45px;
      text-align: center;
      color: lighten($primary, 75%);
    }
  }

  .small-action-desc {
    padding: 0 1.5%;
    text-transform: uppercase;
    font-weight: bold;
    font-size: 0.9em;
    color: lighten($primary, 50%);

    .custom-message {
      text-transform: none;
      margin: 15px 0px 5px;
      font-weight: normal;
      font-size: 14px;
      p {
        margin: 0;
      }
    }

    .avatar {
      margin-right: 0.8em;
      float: left;
    }

    > p {
      margin: 0;
    }
  }

  button {
    background: transparent;
    border: 0;
    float: right;
  }

  clear: both;
}
"}]}

